#include <iostream>
#include <sstream>
#include <cstring>

struct StudentRecord {
    char firstName[25];
    char mi;
    char lastName[25];
    int score;
};

StudentRecord makeStudent(const char* first, char mi, const char* last, int score) {
    StudentRecord s{};
    std::strncpy(s.firstName, first, sizeof(s.firstName) - 1);
    s.mi = mi;
    std::strncpy(s.lastName, last, sizeof(s.lastName) - 1);
    s.score = score;
    return s;
}

void printStudent(const StudentRecord& s) {
    std::cout << s.firstName << " " << s.mi << " " << s.lastName << " " << s.score << "\n";
}

int main() {
    std::stringstream binStream(std::ios::in | std::ios::out | std::ios::binary);

    StudentRecord s1 = makeStudent("John", 'T', "Smith", 90);
    StudentRecord s2 = makeStudent("Eric", 'K', "Jones", 85);

    // Write raw bytes
    binStream.write(reinterpret_cast<const char*>(&s1), sizeof(StudentRecord));
    binStream.write(reinterpret_cast<const char*>(&s2), sizeof(StudentRecord));

    // Reset read position to start
    binStream.seekg(0, std::ios::beg);

    StudentRecord readBack{};
    binStream.read(reinterpret_cast<char*>(&readBack), sizeof(StudentRecord));
    printStudent(readBack);

    binStream.read(reinterpret_cast<char*>(&readBack), sizeof(StudentRecord));
    printStudent(readBack);

    return 0;
}

#include <iostream>
#include <sstream>

struct Record {
    int id;
    double value;
};

int main() {
    std::stringstream stream(std::ios::in | std::ios::out | std::ios::binary);

    // Write 5 records
    for (int i = 0; i < 5; ++i) {
        Record r{i + 1, (i + 1) * 10.5};
        stream.write(reinterpret_cast<const char*>(&r), sizeof(Record));
    }

    // Jump directly to the 3rd record (index 2: offset = 2 * sizeof(Record))
    std::streampos targetOffset = 2 * sizeof(Record);
    stream.seekg(targetOffset, std::ios::beg);
    std::cout << "Current position: " << stream.tellg() << "\n";

    Record thirdRecord{};
    stream.read(reinterpret_cast<char*>(&thirdRecord), sizeof(Record));
    std::cout << "Record 3: ID=" << thirdRecord.id << ", Value=" << thirdRecord.value << "\n";
    std::cout << "Position after read: " << stream.tellg() << "\n";

    // Jump backward relative to current location to read the 2nd record
    stream.seekg(-2 * static_cast<std::streamoff>(sizeof(Record)), std::ios::cur);
    Record secondRecord{};
    stream.read(reinterpret_cast<char*>(&secondRecord), sizeof(Record));
    std::cout << "Record 2: ID=" << secondRecord.id << ", Value=" << secondRecord.value << "\n";

    return 0;
}
